insert into public.businesses (slug, category_id, name_en, name_zh_tw, short_description_en, short_description_zh_tw, description_en, description_zh_tw, city, region, address, service_area_text, phone, email, website, languages, search_aliases, verified, bilingual, newcomer_friendly, sponsored, featured, status, verification_state, last_updated)
values ($lx$desert-river-realty-phoenix$lx$, (select id from public.business_categories where slug = $lx$real-estate$lx$), $lx$Desert River Realty LLC$lx$, $lx$豐盛居地產$lx$, $lx$Phoenix real estate brokerage advertising in Chinese: homes, commercial buildings, land, rentals and business sales.$lx$, $lx$鳳凰城房地產經紀公司，以中文刊登廣告，經營住宅、商業大樓、土地、出租管理及生意買賣。$lx$, $lx$Desert River Realty LLC (豐盛居地產) is a real estate brokerage at 10000 N 31st Ave, Suite D218, in north-west Phoenix, with agent Lethe Lew (廖秀媚). Its Chinese-language ad lists home sales, commercial buildings, land and storefronts, rental management and business sales. Call (602) 266-1238; the ad does not name a dialect, so ask which Chinese languages are spoken. Advertises in Chinese in Next Weekly (亞利桑那州壹週報), checked November 2026.$lx$, $lx$豐盛居地產（Desert River Realty LLC）是位於鳳凰城西北區 10000 N 31st Ave, Suite D218 的房地產經紀公司，經紀人為廖秀媚（Lethe Lew）。中文廣告列出的服務包括住宅買賣、商業大樓、土地及店面、出租管理和生意買賣。電話 (602) 266-1238；廣告未註明方言，來電可先詢問。於《亞利桑那州壹週報》刊登中文廣告，2026 年 11 月查核。$lx$, $lx$Phoenix$lx$, $lx$Greater Phoenix$lx$, $lx$10000 N 31st Ave, Suite D218, Phoenix, AZ 85051$lx$, null, $lx$(602) 266-1238$lx$, null, null, array[$lx$English$lx$, $lx$Chinese$lx$]::text[], array[$lx$Desert River Realty LLC$lx$, $lx$豐盛居地產$lx$, $lx$Phoenix$lx$, $lx$real-estate$lx$, $lx$English$lx$, $lx$Chinese$lx$, $lx$realtor real estate agent$lx$, $lx$房地產經紀人 買房$lx$, $lx$Lethe Lew$lx$, $lx$廖秀媚$lx$, $lx$realtor$lx$, $lx$房地產經紀$lx$, $lx$買房 賣房$lx$, $lx$property management$lx$, $lx$物業管理$lx$, $lx$Chinese-speaking$lx$, $lx$中文服務$lx$]::text[], true, true, false, false, false, $lx$live$lx$, $lx$editor_verified$lx$, now())
on conflict (slug) do nothing;

insert into public.businesses (slug, category_id, name_en, name_zh_tw, short_description_en, short_description_zh_tw, description_en, description_zh_tw, city, region, address, service_area_text, phone, email, website, languages, search_aliases, verified, bilingual, newcomer_friendly, sponsored, featured, status, verification_state, last_updated)
values ($lx$grace-chen-cpa-tempe$lx$, (select id from public.business_categories where slug = $lx$legal-finance$lx$), $lx$Grace Chen, CPA, MBA$lx$, $lx$馬昌華會計師$lx$, $lx$Tempe CPA in practice since 1992: tax, bookkeeping, payroll and overseas income reporting, in Mandarin, Cantonese and English.$lx$, $lx$坦佩會計師，1992 年起在亞利桑那執業：報稅、記帳、薪資及海外收入申報，可說國語、粵語及英語。$lx$, $lx$Grace Chen, CPA, MBA (馬昌華) has an office at 2435 E Southern Ave, Suite 1, in Tempe, and according to the firm's ad has practiced in Arizona since 1992. The ad lists bookkeeping, payroll, business and personal tax returns, company registration, IRS audits, real estate tax planning, foreign income reporting, non-resident returns, and overseas accounts and gifts. Services in Mandarin, Cantonese and English. Advertises in Chinese in Next Weekly (亞利桑那州壹週報), checked November 2026.$lx$, $lx$馬昌華會計師（Grace Chen, CPA, MBA）辦公室位於坦佩（Tempe）2435 E Southern Ave, Suite 1，依廣告自 1992 年起在亞利桑那執業。廣告列出的服務包括記帳、薪資、公司及個人報稅、公司註冊、IRS 查帳、房地產稅務規劃、海外收入申報、非居民報稅，以及海外帳戶與贈與申報。可用國語、粵語及英語服務。於《亞利桑那州壹週報》刊登中文廣告，2026 年 11 月查核。$lx$, $lx$Tempe$lx$, $lx$Greater Phoenix$lx$, $lx$2435 E Southern Ave, Suite 1, Tempe, AZ 85282$lx$, null, $lx$(480) 756-0232$lx$, null, null, array[$lx$English$lx$, $lx$Mandarin$lx$, $lx$Cantonese$lx$]::text[], array[$lx$Grace Chen, CPA, MBA$lx$, $lx$馬昌華會計師$lx$, $lx$Tempe$lx$, $lx$legal-finance$lx$, $lx$English$lx$, $lx$Mandarin$lx$, $lx$Cantonese$lx$, $lx$CPA tax accountant$lx$, $lx$會計師 報稅$lx$, $lx$CPA tax accountant$lx$, $lx$會計師 報稅$lx$, $lx$international tax$lx$, $lx$海外收入申報$lx$, $lx$bookkeeping$lx$, $lx$記帳$lx$, $lx$Chinese-speaking$lx$, $lx$中文服務$lx$]::text[], true, true, false, false, false, $lx$live$lx$, $lx$editor_verified$lx$, now())
on conflict (slug) do nothing;

insert into public.businesses (slug, category_id, name_en, name_zh_tw, short_description_en, short_description_zh_tw, description_en, description_zh_tw, city, region, address, service_area_text, phone, email, website, languages, search_aliases, verified, bilingual, newcomer_friendly, sponsored, featured, status, verification_state, last_updated)
values ($lx$api-dental-group-phoenix$lx$, (select id from public.business_categories where slug = $lx$medical$lx$), $lx$API Dental Group (Chen Yuan, DMD)$lx$, $lx$袁晨牙醫$lx$, $lx$Phoenix general dentist Dr. Chen Yuan, practicing since 2000, with Mandarin, Cantonese and English service; accepts AHCCCS.$lx$, $lx$鳳凰城袁晨牙醫，2000 年起執業，可說國語、粵語及英語，接受 AHCCCS 等多數保險。$lx$, $lx$API Dental Group (袁晨牙醫) is the dental practice of Dr. Chen Yuan, DMD, at 6605 N 19th Ave, Suite F, in Phoenix. The practice's website says Dr. Yuan has practiced dentistry since 2000, and its Chinese ad lists general dentistry, periodontal care, extractions, crowns, bridges, root canals and dentures, with most insurance accepted, including AHCCCS. Service in Mandarin, Cantonese and English. The address and phone are from the practice's website and match the federal NPI registry (the ad gives 6619 N 19th Ave). Advertises in Chinese in Next Weekly (亞利桑那州壹週報), checked November 2026.$lx$, $lx$袁晨牙醫（API Dental Group）是袁晨醫師（Chen Yuan, DMD）的牙科診所，位於鳳凰城 6605 N 19th Ave, Suite F。診所網站表示袁醫師自 2000 年起執業；中文廣告列出一般牙科、牙周治療、拔牙、牙冠、牙橋、根管治療及假牙，接受包括 AHCCCS 在內的多數保險。可用國語、粵語及英語服務。地址與電話依據診所網站，並與聯邦 NPI 登記資料相同（廣告上的地址為 6619 N 19th Ave）。於《亞利桑那州壹週報》刊登中文廣告，2026 年 11 月查核。$lx$, $lx$Phoenix$lx$, $lx$Greater Phoenix$lx$, $lx$6605 N 19th Ave, Suite F, Phoenix, AZ 85015$lx$, null, $lx$(602) 995-6041$lx$, null, $lx$http://www.apidentalphoenix.com/$lx$, array[$lx$English$lx$, $lx$Mandarin$lx$, $lx$Cantonese$lx$]::text[], array[$lx$API Dental Group (Chen Yuan, DMD)$lx$, $lx$袁晨牙醫$lx$, $lx$Phoenix$lx$, $lx$medical$lx$, $lx$apidentalphoenix.com$lx$, $lx$English$lx$, $lx$Mandarin$lx$, $lx$Cantonese$lx$, $lx$dentist$lx$, $lx$牙醫$lx$, $lx$dentist$lx$, $lx$牙醫$lx$, $lx$AHCCCS$lx$, $lx$dentures$lx$, $lx$假牙$lx$, $lx$Chinese-speaking$lx$, $lx$中文服務$lx$]::text[], true, true, false, false, false, $lx$live$lx$, $lx$editor_verified$lx$, now())
