insert into public.businesses (slug, category_id, name_en, name_zh_tw, short_description_en, short_description_zh_tw, description_en, description_zh_tw, city, region, address, service_area_text, phone, email, website, languages, search_aliases, verified, bilingual, newcomer_friendly, sponsored, featured, status, verification_state, last_updated)
values ($lx$jc-financial-services-phoenix$lx$, (select id from public.business_categories where slug = $lx$legal-finance$lx$), $lx$JC Financial Services LLC (Jeanette Chen)$lx$, null, $lx$West Phoenix bookkeeping, payroll and tax office serving clients in Cantonese, Shanghainese, Mandarin and English.$lx$, $lx$鳳凰城西區記帳、薪資及報稅事務所，可說粵語、上海話、國語及英語。$lx$, $lx$JC Financial Services LLC, run by Jeanette Chen, is at 6201 N 35th Ave, #B3, in west Phoenix; its Chinese ad is headed 陳陽會計師. The ad lists computerized bookkeeping and payroll, personal and business tax returns, company formation, changes and dissolution, and audit help, with service in Cantonese, Shanghainese, Mandarin and English. Call (602) 237-7211. Advertises in Chinese in Next Weekly (亞利桑那州壹週報), checked November 2026.$lx$, $lx$JC Financial Services LLC 由 Jeanette Chen 經營，位於鳳凰城西區 6201 N 35th Ave, #B3，中文廣告標題為「陳陽會計師」。廣告列出的服務包括電腦記帳及薪資、個人及公司報稅、公司成立、變更與解散，以及查帳協助，可用粵語、上海話、國語及英語服務。電話 (602) 237-7211。於《亞利桑那州壹週報》刊登中文廣告，2026 年 11 月查核。$lx$, $lx$Phoenix$lx$, $lx$Greater Phoenix$lx$, $lx$6201 N 35th Ave, #B3, Phoenix, AZ 85017$lx$, null, $lx$(602) 237-7211$lx$, null, null, array[$lx$English$lx$, $lx$Mandarin$lx$, $lx$Cantonese$lx$]::text[], array[$lx$JC Financial Services LLC (Jeanette Chen)$lx$, $lx$Phoenix$lx$, $lx$legal-finance$lx$, $lx$English$lx$, $lx$Mandarin$lx$, $lx$Cantonese$lx$, $lx$bookkeeping$lx$, $lx$記帳$lx$, $lx$tax preparation$lx$, $lx$報稅$lx$, $lx$payroll$lx$, $lx$薪資$lx$, $lx$Shanghainese$lx$, $lx$上海話$lx$, $lx$Chinese-speaking$lx$, $lx$中文服務$lx$]::text[], true, true, false, false, false, $lx$live$lx$, $lx$editor_verified$lx$, now())
