insert into public.businesses (slug, category_id, name_en, name_zh_tw, short_description_en, short_description_zh_tw, description_en, description_zh_tw, city, region, address, service_area_text, phone, email, website, languages, search_aliases, verified, bilingual, newcomer_friendly, sponsored, featured, status, verification_state, last_updated)
values ($lx$dobson-warner-dentistry-chandler$lx$, (select id from public.business_categories where slug = $lx$medical$lx$), $lx$Dobson-Warner Dentistry$lx$, null, $lx$Chandler dental office near Dobson and Warner: same-day crowns, orthodontics and implants, with Mandarin and Cantonese.$lx$, $lx$錢德勒 Dobson 與 Warner 路口附近的牙科診所，提供當日牙冠、矯正及植牙，可說國語及粵語。$lx$, $lx$Dobson-Warner Dentistry is at 2051 W Warner Rd, #23, in Chandler, near the Dobson Road and Warner Road shopping area. Its Chinese ad lists general and cosmetic dentistry, same-day CEREC crowns, orthodontics and implants, with discounts for patients without insurance, and staff who speak English, Mandarin, Cantonese, Vietnamese, Spanish and Tagalog. The ad gives hours of 9 a.m. to 6 p.m. Monday, Tuesday, Thursday and Friday and 8 a.m. to 3 p.m. Saturday, closed Wednesday. Appointments: (480) 917-0181. Advertises in Chinese in Next Weekly (亞利桑那州壹週報), checked November 2026.$lx$, $lx$Dobson-Warner Dentistry 位於錢德勒（Chandler）2051 W Warner Rd, #23，鄰近 Dobson 與 Warner 路口的購物區。中文廣告列出一般及美容牙科、CEREC 當日牙冠、齒列矯正及植牙，無保險病患有優惠，員工可說英語、國語、粵語、越南語、西班牙語及他加祿語。廣告列出的看診時間為週一、二、四、五上午 9 點至下午 6 點，週六上午 8 點至下午 3 點，週三休診。預約電話 (480) 917-0181。於《亞利桑那州壹週報》刊登中文廣告，2026 年 11 月查核。$lx$, $lx$Chandler$lx$, $lx$Greater Phoenix$lx$, $lx$2051 W Warner Rd, #23, Chandler, AZ 85224$lx$, null, $lx$(480) 917-0181$lx$, null, null, array[$lx$English$lx$, $lx$Mandarin$lx$, $lx$Cantonese$lx$]::text[], array[$lx$Dobson-Warner Dentistry$lx$, $lx$Chandler$lx$, $lx$medical$lx$, $lx$English$lx$, $lx$Mandarin$lx$, $lx$Cantonese$lx$, $lx$doctor physician$lx$, $lx$醫師 看診$lx$, $lx$dentist$lx$, $lx$牙醫$lx$, $lx$CEREC$lx$, $lx$implants$lx$, $lx$植牙$lx$, $lx$orthodontics$lx$, $lx$矯正$lx$, $lx$Chinese-speaking$lx$, $lx$中文服務$lx$]::text[], true, true, false, false, false, $lx$live$lx$, $lx$editor_verified$lx$, now())
